// Turn Jev's judgment into one label name, using confidence to decide
// Resolving that name to a Gmail label id happens later, after any missing
// labels have been created, so the id can never be stale.
//
//   confident enough              -> Jev's label
//   unsure but clearly actionable -> Action Required
//   unsure                        -> Needs Review  (never a blind guess)
//
// Tune these two floors against your own mail before trusting the run.
const CONFIDENCE_FLOOR = 0.55;   // Choice confidence needed to auto-file
const NEEDS_REPLY_FLOOR = 0.75;  // Noul probability that counts as "actionable"

const REVIEW_LABEL = 'Needs Review';
const NO_MATCH = 'Other / Uncategorized';   // a Choice option, never a Gmail label

// .all(0, $runIndex) pins this to the CURRENT loop round. Without the run
// index a second round could read round one's emails.
const emails = $('Fetch Unlabelled Emails').all(0, $runIndex);
const round = (n) => Math.round(Number(n) * 1000) / 1000;

return $input.all().map((item, i) => {
  const email = emails[i]?.json ?? {};
  const answers = item.json?.answers ?? {};

  const choice = answers.label?.choice ?? null;
  const confidence = Number(answers.label?.confidence ?? 0);
  const needsReply = Number(answers.needs_reply?.noul ?? 0);

  let labelName;
  let reason;
  if (choice && choice !== NO_MATCH && confidence >= CONFIDENCE_FLOOR) {
    labelName = choice;
    reason = 'confident';
  } else if (needsReply >= NEEDS_REPLY_FLOOR) {
    labelName = 'Action Required';
    reason = 'uncertain category, clearly actionable';
  } else {
    labelName = REVIEW_LABEL;
    reason = choice ? 'confidence below floor' : 'no answer from Jev';
  }

  return {
    json: {
      messageId: email.id,
      threadId: email.threadId,
      from: email.headers?.from ?? '',
      subject: email.headers?.subject ?? '',
      labelName,
      reason,
      jevChoice: choice,
      jevConfidence: round(confidence),
      needsReply: round(needsReply),
      runnerUp: topTwo(answers.label?.probabilities),
      model: item.json?.model ?? null,
    },
    pairedItem: { item: i },
  };
});

// Second-most-likely label, handy when you are tuning CONFIDENCE_FLOOR.
function topTwo(probabilities) {
  if (!probabilities) return null;
  const sorted = Object.entries(probabilities).sort((a, b) => b[1] - a[1]);
  return sorted[1] ? { label: sorted[1][0], p: round(sorted[1][1]) } : null;
}

// Diff the names this round needs against the labels Gmail already has
// Emits ONE item per label that is missing, deduplicated - which is the whole
// point of this node. Fifteen emails can share one new label; creating it
// fifteen times is what made Gmail answer "Label name exists or conflicts".
const norm = (s) => String(s ?? '').toLowerCase().replace(/\s+/g, ' ').trim();

const existing = new Set($input.all().map((l) => norm(l.json.name)));
const wanted = new Set($('Decide Label from Confidence').all(0, $runIndex).map((d) => d.json.labelName).filter(Boolean));

const missing = [...wanted].filter((name) => !existing.has(norm(name)));

// The IF node downstream reads `create`. A sentinel keeps the branch alive when
// there is nothing to do, so the run still reaches Apply Label.
if (missing.length === 0) {
  return [{ json: { create: false, missing: [], existingLabelCount: existing.size } }];
}
return missing.map((labelName) => ({ json: { create: true, labelName } }));

// Attach a fresh Gmail label id to every email decision
// now has an id. Join it back onto the per-email decisions.
const norm = (s) => String(s ?? '').toLowerCase().replace(/\s+/g, ' ').trim();

const REVIEW_LABEL = 'Needs Review';
const labelIdByName = new Map($input.all().map((l) => [norm(l.json.name), l.json.id]));

const out = [];
const unresolved = [];

for (const d of $('Decide Label from Confidence').all(0, $runIndex)) {
  const json = { ...d.json };
  let labelId = labelIdByName.get(norm(json.labelName));

  // Gmail refused to create this one (reserved or conflicting name). Fall back
  // to Needs Review rather than dropping the email on the floor.
  if (!labelId && json.labelName !== REVIEW_LABEL) {
    const fallback = labelIdByName.get(norm(REVIEW_LABEL));
    if (fallback) {
      json.reason = `${json.reason}; "${json.labelName}" could not be created, filed under ${REVIEW_LABEL}`;
      json.labelName = REVIEW_LABEL;
      labelId = fallback;
    }
  }

  if (!labelId) {
    unresolved.push(`${json.labelName} (${json.subject})`);
    continue;   // left unlabelled, so the next run picks it up again
  }
  out.push({ json: { ...json, labelId }, pairedItem: { item: 0 } });
}

if (unresolved.length) {
  console.warn(`Skipped ${unresolved.length} email(s), no Gmail label id: ${unresolved.join(', ')}`);
}
return out;

// Loop guard: re-run the search until the backlog is drained
//
// The search is `has:nouserlabels`, so every email labelled this round drops
// out of the next round's results. That is the whole pagination mechanism -
// there is no cursor to carry, and no risk of re-labelling the same message.
const BATCH_SIZE = 50;   // keep in sync with the Limit on Gmail - Get Unlabeled Messages
const MAX_ROUNDS = 20;   // hard ceiling: 20 x 50 = 1000 emails per execution

const round = $runIndex + 1;
const fetched = $('Fetch Unlabelled Emails').all(0, $runIndex).length;
const labelled = $input.all().length;

const stop =
  labelled === 0      ? 'no email was labelled this round, so another round would repeat it'
  : fetched < BATCH_SIZE ? 'Gmail returned a partial page, so the backlog is drained'
  : round >= MAX_ROUNDS  ? `hit the ${MAX_ROUNDS}-round ceiling; the next scheduled run picks up the rest`
  : null;

console.log(`round ${round}: fetched ${fetched}, labelled ${labelled}${stop ? ' - STOP: ' + stop : ' - continuing'}`);

if (stop) return [];             // no items out = the loop ends, execution succeeds
return [{ json: { round, fetched, labelled } }];
